using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.InteropServices;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using SlopStudio;
class V9GuiTests {
 static BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static List<string> lines=new List<string>();static List<Exception> errors=new List<Exception>();static int failures;static string root;
 static object Field(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);}throw new Exception(n);}static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[] a){for(Type t=o.GetType();t!=null;t=t.BaseType){var method=t.GetMethods(F|BindingFlags.DeclaredOnly).FirstOrDefault(m=>m.Name==n&&m.GetParameters().Length==a.Length);if(method!=null)return method.Invoke(o,a);}throw new Exception(n);}
 static void Check(bool b,string why){if(!b)throw new Exception(why);}static void Test(string name,Action body){int before=errors.Count;try{body();Pump(20);Check(before==errors.Count,"UI exception "+(errors.Count>before?errors.Last().ToString():""));lines.Add("PASS "+name);}catch(Exception e){failures++;lines.Add("FAIL "+name+" :: "+e);}File.WriteAllLines(Path.Combine(root,"gui.txt"),lines);}
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr h,int m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern bool PrintWindow(IntPtr h,IntPtr dc,uint flags);[DllImport("user32.dll")]static extern bool SetKeyboardState(byte[] b);[DllImport("user32.dll")]static extern bool GetKeyboardState(byte[] b);[DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr c);
 static void Pump(int ms){var sw=Stopwatch.StartNew();while(sw.ElapsedMilliseconds<ms){Application.DoEvents();Thread.Sleep(3);}}
 static void Mouse(Control c,int id,double x,double y,int buttons=0){float s=DisplayScale.For(c);int ix=(int)(x*s),iy=(int)(y*s);SendMessage(c.Handle,id,(IntPtr)buttons,(IntPtr)((iy<<16)|(ix&65535)));}
 static void Mods(Keys mods,Action action){var old=new byte[256];GetKeyboardState(old);var state=(byte[])old.Clone();state[16]=(mods&Keys.Shift)!=0?(byte)128:(byte)0;state[17]=(mods&Keys.Control)!=0?(byte)128:(byte)0;state[18]=(mods&Keys.Alt)!=0?(byte)128:(byte)0;SetKeyboardState(state);try{action();}finally{SetKeyboardState(old);}}
 static void Click(Control c,double x,double y,Keys mods=Keys.None){Mods(mods,()=>{Mouse(c,0x201,x,y,1);Mouse(c,0x202,x,y);});Pump(20);}
 static void Drag(Control c,double x,double y,double endX,double endY,Keys mods=Keys.None){Mods(mods,()=>{Mouse(c,0x201,x,y,1);Mouse(c,0x200,endX,endY,1);Mouse(c,0x202,endX,endY);});Pump(30);}
 static void Screenshot(Form f,string name){Pump(70);using(var image=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(image)){IntPtr dc=g.GetHdc();try{Check(PrintWindow(f.Handle,dc,2),"Own window capture failed");}finally{g.ReleaseHdc(dc);}}image.Save(Path.Combine(root,name+".png"));}}
 static void Command(MainForm f,AppCommand cmd){Call(f,"ExecuteCommand",cmd);Pump(25);}static void Shortcut(MainForm f,Keys keys){if(keys==(Keys.Control|Keys.A)){var piano=(Control)Field(f,"_pianoRoll");var timeline=(Control)Field(f,"_timeline");Console.WriteLine("CTX visible="+piano.Visible+" piano="+piano.RectangleToScreen(piano.ClientRectangle)+" tracks="+timeline.RectangleToScreen(timeline.ClientRectangle)+" mouse="+Cursor.Position+" focus="+piano.ContainsFocus);}Check((bool)Call(f,"SendTestShortcut",keys),"Shortcut not handled: "+keys+" pianoContext="+Call(f,"PianoContext")+" text="+Call(f,"IsTextEntryFocused"));Pump(20);}
 static ProjectDocument Project(MainForm f){return (ProjectDocument)Field(f,"_project");}static void PointTo(Control c){c.Focus();Point point=c.PointToScreen(new Point(c.ClientSize.Width/2,c.ClientSize.Height/2));var form=c.FindForm() as MainForm;if(form!=null)Set(form,"_editorPointer",(Func<Point>)(()=>point));}

 [STAThread]static int Main(string[] args){
 root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Environment.SetEnvironmentVariable("SLOPSTUDIO_PROFILE",Path.Combine(root,"profile"));
 SetProcessDpiAwarenessContext((IntPtr)(-4));Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=delegate(object s,ThreadExceptionEventArgs e){errors.Add(e.Exception);};
 Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);UiText.Load("en-US");
 var settings=new AppSettings{AudioBackend="WASAPI"};settings.Integration.QuickStart=false;var locale=LocaleCatalog.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"locales","en-US.json"),"en-US");
 using(var form=new MainForm(settings,locale,false,null)){
 form.Show();Pump(250);var p=new ProjectDocument{Name="V9 GUI",Tempo=120};var t=ProjectFactory.CreateTrack("One",TrackType.Midi);var r1=ProjectFactory.CreateRegion("A",0,64);r1.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=1,Pitch=60,Velocity=100});var r2=ProjectFactory.CreateRegion("B",65,4);r2.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=1,Pitch=64,Velocity=95});t.Regions.Add(r1);t.Regions.Add(r2);
 var second=ProjectFactory.CreateTrack("Two",TrackType.Audio);var third=ProjectFactory.CreateTrack("Three",TrackType.Midi);p.Tracks.Add(t);p.Tracks.Add(second);p.Tracks.Add(third);
 string fixture=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"TestFixtures","FixtureGain.clap");var plug=NativePlugin.Scan(fixture)[0].CreateSlot();t.Plugins.Add(plug);var fx=StockEffects.Create(t.Id,"Compressor");p.Studio.Effects.Add(fx);InsertChain.Set(p.Studio,t.Id,new[]{plug.Id,fx.Id});
 Set(form,"_project",p);((ProjectHistory)Field(form,"_history")).Reset(true);Call(form,"Select",t.Id,r1.Id);Pump(100);
 var timeline=(TimelineEditor)Field(form,"_timeline");var tc=(Control)Field(timeline,"_canvas");var piano=(PianoRollEditor)Field(form,"_pianoRoll");var pc=(Control)Field(piano,"_canvas");var split=(SplitContainer)Field(form,"_workspaceSplit");var lower=(LowerWorkspacePanel)Field(form,"_lowerDock");
 Test("Startup artwork and loading bar reflect initialization stages",()=>{
  using(var splash=new SplashForm()){
   Check(splash.HasArtwork,"Startup artwork missing");splash.Show(form);Pump(40);splash.SetProgress(20,"Settings and language loaded");
   int x=(int)(926f/1672*splash.ClientSize.Width),y=(int)(819f/941*splash.ClientSize.Height);Color before;
   using(var bitmap=new Bitmap(splash.Width,splash.Height)){splash.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));before=bitmap.GetPixel(x,y);}
   splash.SetProgress(80,"Opening audio and session…");Check(splash.Progress==80,"Progress value not updated");
   using(var bitmap=new Bitmap(splash.Width,splash.Height)){splash.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));Check(before.ToArgb()!=bitmap.GetPixel(x,y).ToArgb(),"Progress fill did not move");}
   Screenshot(splash,"startup");splash.Close();
  }
 });
 Test("Master strip exposes both insert types and drag reorders the real chain",()=>{
  var initial=Project(form).Studio.Copy();var state=initial.Copy();var masterPlug=NativePlugin.Scan(fixture)[0].CreateSlot();var masterFx=StockEffects.Create(Guid.Empty,"Compressor");state.MasterPlugins.Add(masterPlug);state.Effects.Add(masterFx);InsertChain.Set(state,Guid.Empty,new[]{masterPlug.Id,masterFx.Id});
  try{
   Call(form,"CommitStudio","Master insert fixture",state);split.Panel2Collapsed=false;lower.ShowMixer();Pump(120);
   var mixer=Field(form,"_mixer");var strip=(ChannelStripControl)Field(mixer,"_master");using(var image=new Bitmap(strip.Width,strip.Height))strip.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));
   var slots=(List<KeyValuePair<Rectangle,PluginSlot>>)Field(strip,"_slots");var native=slots.First(x=>x.Value.Id==masterPlug.Id);var stock=slots.First(x=>x.Value.Id==masterFx.Id);
   Drag(strip,stock.Key.X+8,stock.Key.Y+7,native.Key.X+8,native.Key.Y+7);
   Check(InsertChain.Entries(Project(form),Guid.Empty).Select(x=>x.Id).SequenceEqual(new[]{masterFx.Id,masterPlug.Id}),"Master drag did not change persisted order");
   Call(form,"TogglePlugin",masterPlug);Check(Project(form).Studio.MasterPlugins.Find(x=>x.Id==masterPlug.Id).Bypassed,"Master bypass failed");
  }finally{Call(form,"CommitStudio","Restore master fixture",initial);((ProjectHistory)Field(form,"_history")).Reset(true);}
 });
 Test("MCP manager enables session editing after read-only denial",()=>{
  form.McpMode=true;Set(form,"_mcpAllowEditing",false);int count=Project(form).Tracks.Count;var mcpArgs=new Dictionary<string,object>{{"name","Approved fixture"},{"type","midi"}};bool denied=false;
  try{Call(form,"McpDispatch","create_track",mcpArgs);}catch(TargetInvocationException ex){denied=ex.InnerException is InvalidOperationException;}
  Check(denied&&Project(form).Tracks.Count==count,"MCP changed a project without permission");
  string dialogError=null;bool seen=false;var timer=new System.Windows.Forms.Timer{Interval=80};
  timer.Tick+=delegate{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="MCP AI Integration Manager");if(dialog==null)return;timer.Stop();seen=true;try{var check=Find(dialog).OfType<CheckBox>().Single();Check(check.Enabled&&!check.Checked,"MCP manager did not default to read-only");check.Checked=true;Find(dialog).OfType<Button>().First(x=>x.Text=="Apply").PerformClick();}catch(Exception ex){dialogError=ex.Message;dialog.Close();}};
  timer.Start();try{Call(form,"ShowMcpManager");}finally{timer.Stop();timer.Dispose();}
  Check(seen&&dialogError==null&&(bool)Field(form,"_mcpAllowEditing"),"MCP manager permission failed: "+dialogError);
  Call(form,"McpDispatch","create_track",mcpArgs);Check(Project(form).Tracks.Count==count+1,"Approved MCP edit did not execute");
  Call(form,"Undo");Check(Project(form).Tracks.Count==count,"Approved MCP edit was not undoable");Set(form,"_mcpAllowEditing",false);form.McpMode=false;
 });
 Test("Editor toolbar opens an empty audio editor without creating regions",()=>{Call(form,"Select",second.Id,null);split.Panel2Collapsed=true;var bar=(Control)Field(form,"_controlBar");Click(bar,125,25);Check(!split.Panel2Collapsed&&lower.ShowsEditor((Control)Field(form,"_audioEditor")),"Editor toolbar did not open audio editor");Check(second.Regions.Count==0,"Empty editor created material");});
 Test("Shift wheel pans piano roll and keeps UI scale unchanged",()=>{Call(form,"Select",t.Id,r1.Id);Call(form,"OpenEditor");var h=(StudioScrollBar)Field(piano,"_horizontal");h.Value=0;int scale=settings.UiScale;Point pt=pc.PointToScreen(new Point(pc.ClientSize.Width/2,pc.ClientSize.Height/2));var message=Message.Create(pc.Handle,0x20a,(IntPtr)unchecked((int)(0xff880000u|4u)),(IntPtr)((pt.Y<<16)|(pt.X&65535)));var filter=Field(form,"_wheelFilter");object[] args2={message};Check((bool)Call(filter,"PreFilterMessage",args2),"Wheel not routed");Check(h.Value>0&&settings.UiScale==scale,"Shift-wheel did not pan piano");});
 Test("Ruler drag defines and resizes an undoable cycle",()=>{timeline.SetZoom(8);timeline.ScrollHorizontalTo(0);double x=timeline.HeaderWidth;Drag(tc,x+32,5,x+96,5);Check(p.CycleEnabled&&Math.Abs(p.CycleStartBeat-4)<.01&&Math.Abs(p.CycleEndBeat-12)<.01,"Cycle drag range wrong");Drag(tc,x+96,5,x+128,5);Check(Math.Abs(p.CycleEndBeat-16)<.01,"Right locator did not resize");Call(form,"Undo");Check(Math.Abs(p.CycleEndBeat-12)<.01,"Cycle resize undo failed");});
 Test("Ctrl+J joins selected MIDI regions and undo restores them",()=>{PointTo(tc);var selected=(HashSet<Guid>)Field(tc,"SelectedRegions");selected.Clear();selected.Add(r1.Id);selected.Add(r2.Id);Shortcut(form,Keys.Control|Keys.J);var current=Project(form).Tracks.Find(x=>x.Id==t.Id);Check(current.Regions.Count==1&&current.Regions[0].Notes.Count==2,"Joined region missing notes");Call(form,"Undo");current=Project(form).Tracks.Find(x=>x.Id==t.Id);Check(current.Regions.Count==2,"Join undo failed");});
 Test("Built-in and external inserts display together and drag changes the saved order",()=>{Call(form,"Select",t.Id,null);split.Panel2Collapsed=false;lower.ShowMixer();Pump(100);var mixer=Field(form,"_mixer");var strips=(Dictionary<Guid,ChannelStripControl>)Field(mixer,"_strips");var strip=strips[t.Id];using(var image=new Bitmap(strip.Width,strip.Height))strip.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));var slots=(List<KeyValuePair<Rectangle,PluginSlot>>)Field(strip,"_slots");var native=slots.First(x=>x.Value.Id==plug.Id);var stock=slots.First(x=>x.Value.Id==fx.Id);Drag(strip,stock.Key.X+8,stock.Key.Y+7,native.Key.X+8,native.Key.Y+7);var project=Project(form);var actual=project.Tracks.Find(x=>x.Id==t.Id);Check(InsertChain.Entries(project,actual).Select(x=>x.Id).SequenceEqual(new[]{fx.Id,plug.Id}),"Drag did not update order");using(var image=new Bitmap(strip.Width,strip.Height))strip.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));slots=(List<KeyValuePair<Rectangle,PluginSlot>>)Field(strip,"_slots");stock=slots.First(x=>x.Value.Id==fx.Id);Click(strip,stock.Key.X+8,stock.Key.Y+7);Check(Application.OpenForms.Cast<Form>().Any(x=>x is StockEffectEditor),"Stock insert did not open editor");foreach(Form w in Application.OpenForms.Cast<Form>().Where(x=>x is StockEffectEditor).ToArray())w.Close();Screenshot(form,"mixer-inserts");});
 Test("Shift-select tracks, context menu creates summing stack and disclosure hides children",()=>{Call(form,"Select",t.Id,null);timeline.SetLaneHeight(46);Pump(40);Click(tc,42,33+8);Click(tc,42,33+46+8,Keys.Shift);Check(timeline.SelectedTracks.Count==2,"Shift track selection failed: "+timeline.SelectedTracks.Count);Mouse(tc,0x204,42,33+46+8,2);Mouse(tc,0x205,42,33+46+8,0);Pump(40);var menu=(ContextMenuStrip)Field(tc,"_contextMenu");var item=menu.Items.Cast<ToolStripItem>().First(x=>x.Text=="Create Mix Stack");item.PerformClick();Pump(100);var project=Project(form);Check(project.Studio.Stacks.Count==1&&project.Studio.Stacks[0].Children.Count==2,"Stack was not created");Guid parent=project.Studio.Stacks[0].ParentId;Check(project.Tracks.Find(x=>x.Id==t.Id).Plugins.Any(x=>x.Id==plug.Id)&&project.Studio.Effects.Any(x=>x.Id==fx.Id),"Child plug-ins were lost");Click(tc,10,33+8);Check(project.Studio.Stacks[0].Collapsed&&TrackRouting.Visible(project).Count==2,"Stack disclosure did not collapse");Screenshot(form,"collapsed-stack");});
 Test("Track inspector header toggles detail row",()=>{var inspector=(Control)Field(form,"_inspector");var header=(Control)Field(inspector,"_trackHeader");var table=(TableLayoutPanel)Field(inspector,"_rootLayout");float before=table.RowStyles[3].Height;Call(header,"OnClick",EventArgs.Empty);Check(table.RowStyles[3].Height==0,"Track inspector did not collapse");Call(header,"OnClick",EventArgs.Empty);Check(table.RowStyles[3].Height>0&&before>0,"Track inspector did not reopen");});
 Test("Shortcut preferences use Windows defaults and canvas does not disable text IME",()=>{using(var prefs=new PreferencesForm(settings)){prefs.Show(form);Pump(50);var grid=Find(prefs).OfType<DataGridView>().Single();Check(grid.Columns.Cast<DataGridViewColumn>().Any(c=>c.HeaderText=="Default Shortcut")&&!grid.Columns.Cast<DataGridViewColumn>().Any(c=>c.HeaderText.Contains("legacy platform")),"Wrong key columns");prefs.Close();}Check(tc.ImeMode==ImeMode.Disable,"Editing canvas IME mode");var inspector=(Control)Field(form,"_inspector");var box=(TextBox)Field(inspector,"_trackName");Check(box.ImeMode!=ImeMode.Disable,"Text entry IME disabled");});
 Test("Sampler window shows import/record controls and commits ADSR changes",()=>{var project=Project(form);var track=project.Tracks.Find(x=>x.Id==t.Id);Call(form,"Select",track.Id,null);Call(form,"OpenSampler",track);Pump(80);var sampler=Application.OpenForms.Cast<Form>().First(x=>x is SamplerEditor);var all=Find(sampler).ToList();Check(all.OfType<Button>().Any(x=>x.Text.Contains("Import Sample"))&&all.OfType<Button>().Any(x=>x.Text=="Record Sample"),"Sampler controls missing");var numbers=all.OfType<NumericUpDown>().ToList();Check(numbers.Count>=5,"ADSR controls missing");numbers[1].Value=.125m;Pump(70);Check(Math.Abs(project.Studio.Sampler(track.Id).Attack-.125)<.0001,"ADSR change not saved");Screenshot(sampler,"sampler");sampler.Close();});
 ((ProjectHistory)Field(form,"_history")).Reset(true);Set(form,"_closing",true);form.Close();
 }
 lines.Add("NOT RUN physical Japanese IME typing, mouse drag, MIDI keyboard or microphone performance.");File.WriteAllLines(Path.Combine(root,"gui.txt"),lines);Console.WriteLine(String.Join(Environment.NewLine,lines.ToArray()));return failures==0?0:1;
 }
 static IEnumerable<Control> Find(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in Find(c))yield return nested;}}
